window.VeilGardeData.files["Sources-VeilGardeInference"] = {"group":"Sources-VeilGardeInference","files":[{"path":"Sources/VeilGardeInference/Bundle/DetectorBundle.swift","status":"added","lang":"swift","hunks":[[1,0,1,56]],"header":{"lines":[1,12],"target":"VeilGardeInference","what":[6,8],"pin":[9,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":383,"scopes":[["S","DetectorBundle",null,"public",16,16,[16,50],56,null,-1,0,"a"],["i","init",["directory","manifest"],"public",20,20,[20,58],23,null,0,0,"a"],["v","shipped",null,"public static",26,26,[26,46],26,[25,25],0,8,"a"],["f","load",["_"],"public static",29,29,[29,71],32,[28,28],0,0,"a"],["f","url",["_","head"],"public",34,34,[34,73],36,null,0,0,"a"],["v","isShipped",null,"public",38,38,[38,31],38,null,0,8,"a"],["v","hashes",null,"public",41,41,[41,36],45,[40,40],0,0,"a"],["v","provenance",null,"public",49,49,[49,44],55,[47,48],0,0,"a"]],"old":"","new":"//\n//  DetectorBundle.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The set of artifacts one detection reads: the shipped bundle by default, or another\n//        hash-bound bundle directory (the flywheel's live bundle, a staged candidate) so the\n//        battery can judge exactly what promote would deploy.\n//  PIN:  A loaded bundle is verified (every artifact re-hashed against its manifest); the shipped\n//        one is verified once per process by ShippedBundle. Artifacts are resolved by role, never\n//        by file name, so a promoted head under a new name is found.\n//\n\nimport Foundation\n\npublic struct DetectorBundle: Sendable, Equatable {\n    public let directory: URL\n    public let manifest: BundleManifest\n\n    public init(directory: URL, manifest: BundleManifest) {\n        self.directory = directory\n        self.manifest = manifest\n    }\n\n    /// The bundle the package ships.\n    public static var shipped: DetectorBundle { DetectorBundle(directory: ShippedBundle.directory, manifest: ShippedBundle.manifest) }\n\n    /// A bundle directory, every artifact verified.\n    public static func load(_ directory: URL) throws -> DetectorBundle {\n        let bundle = try ModelBundle.load(directory)\n        return DetectorBundle(directory: bundle.root, manifest: bundle.manifest)\n    }\n\n    public func url(_ role: ArtifactRole, head: HeadKind? = nil) -> URL? {\n        manifest.artifact(role, head: head).map { directory.appendingPathComponent($0.file) }\n    }\n\n    public var isShipped: Bool { directory.standardizedFileURL == ShippedBundle.directory.standardizedFileURL }\n\n    /// The hashes a result reports: the fusion head's, the combiner's and the manifest's.\n    public var hashes: BundleHashes {\n        let manifestSHA = (try? JSONCoding.prettyEncoder().encode(manifest)).map { ContentHash.sha256Hex($0) } ?? \"\"\n        return BundleHashes(fusionHeadSHA256: manifest.artifact(.fusionHead)?.sha256, combinerSHA256: manifest.artifact(.combiner)?.sha256,\n                            manifestSHA256: manifestSHA)\n    }\n\n    /// What a report names to say which models it measured: the bundle's directory, the fusion\n    /// head's and the combiner's hashes, and the manifest's hash.\n    public var provenance: [String: String] {\n        let h = hashes\n        var out = [\"bundle\": directory.path, \"manifest_sha256\": h.manifestSHA256]\n        if let f = h.fusionHeadSHA256 { out[\"fusion_head_sha256\"] = f }\n        if let c = h.combinerSHA256 { out[\"combiner_sha256\"] = c }\n        return out\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Bundle/ShippedBundle.swift","status":"added","lang":"swift","hunks":[[1,0,1,67]],"header":{"lines":[1,12],"target":"VeilGardeInference","what":[6,7],"pin":[8,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":391,"scopes":[["E","ShippedBundle",null,"public",16,16,[16,26],67,null,-1,0,"a",[]],["f","verified",[],"public static",40,40,[40,56],47,[39,39],0,0,"a"],["f","url",["_","head"],"public static",50,50,[50,79],55,[49,49],0,0,"a"],["f","registerWeightFolders",["workArea"],"public static",59,59,[59,87],66,[57,58],0,0,"a"]],"old":"","new":"//\n//  ShippedBundle.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The detector bundle this package ships: the artifacts it was verified with, bound by\n//        manifest.json. Everything that reads a shipped artifact asks here, by role.\n//  PIN:  The only file that writes `Bundle.module` (PackageLayeringTests). The bundle is verified\n//        once per process the first time it is used: every artifact re-hashed against the\n//        manifest, a mismatch refused. Its resource folder is registered with the WeightLocator,\n//        after the work area's weights/, for weights copied into the Inference resources.\n//\n\nimport Foundation\n\npublic enum ShippedBundle {\n    /// The folder holding manifest.json and the artifacts.\n    public static let directory: URL = {\n        let module = Bundle.module\n        for candidate in [module.resourceURL, module.bundleURL].compactMap({ $0 })\n        where FileManager.default.fileExists(atPath: candidate.appendingPathComponent(BundleManifest.fileName).path) {\n            return candidate\n        }\n        if let manifest = module.url(forResource: \"manifest\", withExtension: \"json\") { return manifest.deletingLastPathComponent() }\n        fatalError(\"VeilGardeInference's resource bundle has no manifest.json; rebuild the package\")\n    }()\n\n    private static let lock = NSLock()\n    nonisolated(unsafe) private static var verifiedBundle: ModelBundle?\n    nonisolated(unsafe) private static var registered = false\n\n    /// The manifest as shipped (not re-hashed).\n    public static let manifest: BundleManifest = {\n        do { return try JSONCoding.read(BundleManifest.self, from: directory.appendingPathComponent(BundleManifest.fileName)) } catch {\n            fatalError(\"the shipped manifest.json does not decode: \\(error)\")\n        }\n    }()\n\n    /// The shipped bundle, every artifact re-hashed once per process.\n    public static func verified() throws -> ModelBundle {\n        lock.lock()\n        defer { lock.unlock() }\n        if let verifiedBundle { return verifiedBundle }\n        let bundle = try ModelBundle.load(directory)\n        verifiedBundle = bundle\n        return bundle\n    }\n\n    /// The shipped artifact for a role; every role the detector reads is in the manifest.\n    public static func url(_ role: ArtifactRole, head: HeadKind? = nil) -> URL {\n        guard let artifact = manifest.artifact(role, head: head) else {\n            fatalError(\"the shipped bundle has no \\(head.map { \"head:\\($0.rawValue)\" } ?? role.rawValue)\")\n        }\n        return directory.appendingPathComponent(artifact.file)\n    }\n\n    /// Registers the weight folders: the work area's weights/ (when there is a work area), then\n    /// this bundle's resources. Idempotent.\n    public static func registerWeightFolders(workArea: WorkArea? = WorkArea.resolve()) {\n        lock.lock()\n        defer { lock.unlock() }\n        guard !registered else { return }\n        registered = true\n        if let workArea { WeightLocator.shared.register(workArea.weights) }\n        WeightLocator.shared.register(directory)\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Config/InferenceConfig.swift","status":"added","lang":"swift","hunks":[[1,0,1,36]],"header":{"lines":[1,10],"target":"VeilGardeInference","what":[6,7],"pin":[8,9],"in":null,"out":null,"style":"swift"},"marks":[],"first":395,"scopes":[["S","InferenceConfig",null,"public",14,14,[14,40],36,null,-1,0,"a"],["i","init",["bundle","decision","dinoVariant","semanticResponsibility"],"public",25,25,[26,75],32,null,0,0,"a"],["v","shipped",null,"public static",35,35,[35,47],35,[34,34],0,8,"a"]],"old":"","new":"//\n//  InferenceConfig.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: How one detection runs: the bundle it reads, the verdict's operating point, the semantic\n//        backbone's size, and how much authority the semantic mechanisms have.\n//  PIN:  The defaults are the shipped detector's: the shipped bundle, 0.5 ± 0.04, DINOv2-small and\n//        the `.control` profile. The diagnostic and removed profiles are ablations.\n//\n\nimport Foundation\n\npublic struct InferenceConfig: Sendable {\n    /// The artifacts this detection reads (the shipped bundle unless told otherwise).\n    public var bundle: DetectorBundle\n    /// The verdict's operating point, 0.5 ± 0.04 (the screenshot head keeps its own threshold with this band).\n    public var decision: DecisionRule\n    public var dinoVariant: DinoVariant\n    /// Production `.control`; the diagnostic and removed profiles are ablations.\n    public var semanticResponsibility: SemanticResponsibility\n    /// The frame-interior mechanism's recursion guard; never set by callers.\n    public var skipFrameCheck: Bool\n\n    public init(bundle: DetectorBundle = .shipped, decision: DecisionRule = .fusion, dinoVariant: DinoVariant = .small,\n                semanticResponsibility: SemanticResponsibility = .control) {\n        self.bundle = bundle\n        self.decision = decision\n        self.dinoVariant = dinoVariant\n        self.semanticResponsibility = semanticResponsibility\n        self.skipFrameCheck = false\n    }\n\n    /// The shipped defaults.\n    public static var shipped: InferenceConfig { InferenceConfig() }\n}\n"},{"path":"Sources/VeilGardeInference/Fusion/FusionInference.swift","status":"added","lang":"swift","hunks":[[1,0,1,63]],"header":{"lines":[1,17],"target":"VeilGardeInference","what":[6,10],"pin":[11,16],"in":null,"out":null,"style":"swift"},"marks":[],"first":398,"scopes":[["E","Fusion",null,"public",22,22,[22,19],63,null,-1,0,"a",[]],["f","vector",["_","layout","capture"],"static",25,25,[25,111],31,[23,24],0,0,"a"],["f","verdict",["_"],"public static",34,34,[34,80],43,[33,33],0,0,"a"],["f","screenshotGuard",["_"],"static",47,47,[47,75],52,[45,46],0,0,"a"],["f","neutralizedBaseP",["_"],"static",55,55,[55,66],62,[54,54],0,0,"a"]],"old":"","new":"//\n//  FusionInference.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The camera base expert: DINOv2 and the nine capture values through the fusion head, one\n//        P(AI) at 0.5 ± band. The head's width names its row (FusionLayout): the plain CLS and\n//        capture, 393 columns, or both DINOv2 readings and capture, 777. If the flat-UI gate fires,\n//        the screenshot head takes the verdict (or \"real\" without that head). Also the base\n//        probability with the capture-validity shortcut neutralized, which the preview tail asks for.\n//  PIN:  Column order is the layout's (FusionLayout.columns). The force-resized reading is the one\n//        the specialist heads read, cached in the signals, so the wider row costs no DINOv2 pass.\n//        The head and the band come from the config's bundle and decision rule. Neutralizing sets valid = 1 and native px =\n//        max(·, 576): invalid-capture rows were 85.5% generated in the 2026-07-17 measurement and\n//        taught the base \"small ⇒ AI\". The preview tail's cuts were set against the head before\n//        2026-10-21; they are kept, and the tail's firing is reported in route_diagnostics.\n//\n\nimport CoreGraphics\nimport Foundation\n\npublic enum Fusion {\n    /// The row in a layout: the plain DINOv2 embedding, the force-resized one for `.bothReadings`,\n    /// and the nine capture values (`capture` stands in for them when given).\n    static func vector(_ s: DetectionSignals, layout: FusionLayout, capture: [Float]? = nil) throws -> [Float] {\n        let cap = capture ?? CaptureLens.features(s.cgImage).asVector\n        switch layout {\n        case .dinoCapture: return try s.dinoFusion() + cap\n        case .bothReadings: return try s.dinoFusion() + s.dinoNorm() + cap\n        }\n    }\n\n    /// The camera base expert's verdict.\n    public static func verdict(_ s: DetectionSignals) throws -> InferenceResult {\n        guard let headURL = s.config.bundle.url(.fusionHead) else { throw VeilGardeFailure.missing(\"the bundle has no fusion head\") }\n        if let guarded = screenshotGuard(s) { return guarded }\n        let head = try TreeModelCache.shared.model(headURL)\n        let p = head.predict(try vector(s, layout: FusionLayout.of(width: head.numFeatures)))\n        let rule = s.config.decision\n        return InferenceResult(scorer: \"fusion\", prediction: s.gate.isScreenshot ? \"real\" : rule.label(p), p: p,\n                               threshold: rule.threshold, band: rule.band, imageWidth: s.width, imageHeight: s.height,\n                               captureSignature: s.capture())\n    }\n\n    /// The flat-UI gate inside the camera base: when it fires and the bundle has a screenshot head,\n    /// that head's verdict is the base's. Nil otherwise.\n    static func screenshotGuard(_ s: DetectionSignals) -> InferenceResult? {\n        guard s.gate.isScreenshot, let sv = ScreenshotSpecialist.verdict(s.cgImage, config: s.config) else { return nil }\n        let t = HeadRegistry.shared.head(.screenshot, in: s.config.bundle)?.threshold ?? 0.5\n        return InferenceResult(scorer: \"screenshot\", prediction: sv.verdict, p: sv.p, threshold: t, band: s.config.decision.band,\n                               imageWidth: s.width, imageHeight: s.height, captureSignature: sv.capture)\n    }\n\n    /// The base probability with the capture-validity flags neutralized (the preview tail's arbiter).\n    static func neutralizedBaseP(_ s: DetectionSignals) -> Float? {\n        guard let url = s.config.bundle.url(.fusionHead), let head = try? TreeModelCache.shared.model(url),\n              let layout = try? FusionLayout.of(width: head.numFeatures) else { return nil }\n        var cap = CaptureLens.features(s.cgImage).asVector\n        if cap.count >= 4 { cap[1] = 1.0; cap[3] = max(cap[3], 576.0) }\n        guard let row = try? vector(s, layout: layout, capture: cap) else { return nil }\n        return head.predict(row)\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Route/Detector.swift","status":"added","lang":"swift","hunks":[[1,0,1,66]],"header":{"lines":[1,14],"target":"VeilGardeInference","what":[6,9],"pin":[10,13],"in":null,"out":null,"style":"swift"},"marks":[],"first":403,"scopes":[["C","Detector",null,"public final",19,19,[19,49],66,null,-1,0,"a"],["i","init",[],"public",26,26,[26,18],29,null,0,0,"a"],["f","register",["_"],"public",31,31,[31,45],31,null,0,8,"a"],["f","register",["override"],"public",32,32,[32,53],32,null,0,8,"a"],["f","setDomainDetector",["_"],"public",33,33,[33,55],33,null,0,8,"a"],["f","snapshot",[],"private",35,35,[35,97],39,null,0,0,"a"],["f","detect",["cgImage","config","hint"],"public",42,42,[42,157],65,[41,41],0,0,"a"]],"old":"","new":"//\n//  Detector.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The router, the one entry point of the full detector. It picks the image's domain, runs\n//        that domain's base expert (camera: the fusion head; screenshot: the content head), then\n//        compounds the high-precision priors on it in a fixed order: capture and the pooled\n//        specialists, the frame seam, the semantic chain. One verdict comes out.\n//  PIN:  The reference router's order and arithmetic, split one mechanism per file. Stacking, not\n//        blending: a monolithic combiner regressed real false positives 8% → 50–92% in the\n//        research's measurement, the stack holds them at 0%. Routing is never by image size. The\n//        state is frozen before the semantic chain (preSemantic) for replay.\n//\n\nimport CoreGraphics\nimport Foundation\n\npublic final class Detector: @unchecked Sendable {\n    public static let shared = Detector()\n    private let lock = NSLock()\n    private var heads: [DetectionDomain: DomainHead] = [:]\n    private var overrides: [DomainOverride] = []\n    private var domainDetector: DomainDetector = DefaultDomainDetector()\n\n    public init() {\n        register(CameraFusionHead())\n        register(ScreenshotContentHead())\n    }\n\n    public func register(_ head: DomainHead) { lock.lock(); heads[head.domain] = head; lock.unlock() }\n    public func register(override o: DomainOverride) { lock.lock(); overrides.append(o); lock.unlock() }\n    public func setDomainDetector(_ d: DomainDetector) { lock.lock(); domainDetector = d; lock.unlock() }\n\n    private func snapshot() -> (DomainDetector, [DetectionDomain: DomainHead], [DomainOverride]) {\n        lock.lock()\n        defer { lock.unlock() }\n        return (domainDetector, heads, overrides)\n    }\n\n    /// The full verdict for one image.\n    public func detect(cgImage: CGImage, config: InferenceConfig, hint: DetectionDomain? = nil) throws -> (result: InferenceResult, domain: DetectionDomain) {\n        let s = DetectionSignals(cgImage: cgImage, config: config)\n        let (picker, registered, _) = snapshot()\n        let domain = picker.detect(s, hint: hint)\n        let base = try (registered[domain] ?? registered[.camera]!).verdict(s)\n\n        var state = RouteState(base: base)\n        let cap = s.capture()\n        CapturePriors.apply(&state, s, domain: domain, capture: cap)\n        try FrameSeam.apply(&state, s, capture: cap, hint: hint, detector: self)\n        let preSemanticP = state.p\n        let preSemanticPrediction = state.verdict\n        let semanticTiles = SemanticChain.apply(&state, s, capture: cap)\n\n        let diagnostics = RouteDiagnostics(\n            route: domain.rawValue, requestedHint: hint?.rawValue, semanticProfile: config.semanticResponsibility.rawValue,\n            screenshotGate: s.gate.isScreenshot, baseP: base.p, preSemanticP: preSemanticP, preSemanticPrediction: preSemanticPrediction,\n            semanticMajority: state.semanticMajority, semanticEvaluated: state.semanticEvaluated, semanticTriggered: state.semanticTriggered,\n            semanticDecisive: state.semanticDecisive, previewEvaluated: state.previewEvaluated, previewTriggered: state.previewTriggered,\n            previewDecisive: state.previewDecisive)\n        let result = PublicSurface.routed(base: base, prediction: state.verdict, p: state.p, capture: cap, specialists: state.stack,\n                                          semanticTiles: semanticTiles, routeDiagnostics: diagnostics, bundle: config.bundle.hashes)\n        return (result, domain)\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Route/Domain.swift","status":"added","lang":"swift","hunks":[[1,0,1,37]],"header":{"lines":[1,13],"target":"VeilGardeInference","what":[6,9],"pin":[10,12],"in":null,"out":null,"style":"swift"},"marks":[],"first":410,"scopes":[["P","DomainHead",null,"public",15,15,[15,37],18,null,-1,0,"a"],["v","domain",null,"",16,16,[16,32],16,null,0,9,"a"],["f","verdict",["_"],"",17,17,null,17,null,0,1,"a"],["P","DomainDetector",null,"public",20,20,[20,41],22,null,-1,0,"a"],["f","detect",["_","hint"],"",21,21,null,21,null,3,1,"a"],["P","DomainOverride",null,"public",26,26,[26,41],28,[24,25],-1,0,"a"],["f","apply",["_","_"],"",27,27,null,27,null,5,1,"a"],["S","DefaultDomainDetector",null,"public",30,30,[30,52],37,null,-1,0,"a"],["i","init",[],"public",31,31,[31,18],31,null,7,8,"a"],["f","detect",["_","hint"],"public",33,33,[33,89],36,null,7,0,"a"]],"old":"","new":"//\n//  Domain.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The router's extension points: a domain head (the base expert for one domain), the\n//        domain detector that picks it, and a cross-cutting override applied after the head.\n//        Adding a domain is a head trained on the shared embedding, a detector that knows the\n//        domain, and one `Detector.shared.register(head)`; nothing else moves.\n//  PIN:  Garde's protocols. The default detector: a caller's hint wins, else the flat-UI gate marks\n//        a screenshot, else camera. The gate misses photographic reel screenshots, so a caller with\n//        context (a share extension) passes the screenshot hint.\n//\n\npublic protocol DomainHead: Sendable {\n    var domain: DetectionDomain { get }\n    func verdict(_ s: DetectionSignals) throws -> InferenceResult\n}\n\npublic protocol DomainDetector: Sendable {\n    func detect(_ s: DetectionSignals, hint: DetectionDomain?) -> DetectionDomain\n}\n\n/// A high-precision guard applied after the head. Empty by default: the validated capture-present\n/// override lives in the router's stack, scoped to the screenshot domain.\npublic protocol DomainOverride: Sendable {\n    func apply(_ result: InferenceResult, _ s: DetectionSignals) -> InferenceResult\n}\n\npublic struct DefaultDomainDetector: DomainDetector {\n    public init() {}\n\n    public func detect(_ s: DetectionSignals, hint: DetectionDomain?) -> DetectionDomain {\n        if let hint { return hint }\n        return s.gate.isScreenshot ? .screenshot : .camera\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Route/Heads/CameraFusionHead.swift","status":"added","lang":"swift","hunks":[[1,0,1,18]],"header":{"lines":[1,9],"target":"VeilGardeInference","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":420,"scopes":[["S","CameraFusionHead",null,"public",11,11,[11,43],18,null,-1,0,"a"],["i","init",[],"public",13,13,[13,18],13,null,0,8,"a"],["f","verdict",["_"],"public",15,15,[15,73],17,null,0,0,"a"]],"old":"","new":"//\n//  CameraFusionHead.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The camera domain's base expert: the fusion head over DINOv2 and the capture signature,\n//        the spine the specialist stack compounds onto. Registered by default and the fallback for\n//        any domain without its own head.\n//\n\npublic struct CameraFusionHead: DomainHead {\n    public let domain: DetectionDomain = .camera\n    public init() {}\n\n    public func verdict(_ s: DetectionSignals) throws -> InferenceResult {\n        try Fusion.verdict(s)\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Route/Heads/ScreenshotContentHead.swift","status":"added","lang":"swift","hunks":[[1,0,1,29]],"header":{"lines":[1,11],"target":"VeilGardeInference","what":[6,8],"pin":[9,10],"in":null,"out":null,"style":"swift"},"marks":[],"first":423,"scopes":[["S","ScreenshotContentHead",null,"public",13,13,[13,48],29,null,-1,0,"a"],["i","init",[],"public",15,15,[15,18],15,null,0,8,"a"],["f","verdict",["_"],"public",17,17,[17,73],28,null,0,0,"a"]],"old":"","new":"//\n//  ScreenshotContentHead.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The screenshot domain's base expert: the RAW resolution-normalized content P(AI). The\n//        capture-present override is a stack prior in the router, so the stack shows the raw read\n//        and the override separately.\n//  PIN:  Garde's ScreenshotContentHead: the shared 360×640 embedding (signals), the head's own\n//        threshold, the config's band.\n//\n\npublic struct ScreenshotContentHead: DomainHead {\n    public let domain: DetectionDomain = .screenshot\n    public init() {}\n\n    public func verdict(_ s: DetectionSignals) throws -> InferenceResult {\n        guard let head = HeadRegistry.shared.head(.screenshot, in: s.config.bundle) else {\n            throw VeilGardeFailure.missing(\"the bundle has no screenshot head\")\n        }\n        let emb = try s.dinoNorm()\n        let cap = s.capture()\n        let p = head.pAI(emb)\n        let t = head.threshold\n        let verdict = abs(p - t) < s.config.decision.band ? \"inconclusive\" : (p > t ? \"generated\" : \"real\")\n        return InferenceResult(scorer: \"screenshot\", prediction: verdict, p: p, threshold: t, band: s.config.decision.band,\n                               imageWidth: s.width, imageHeight: s.height, captureSignature: cap)\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Route/Mechanisms/CapturePriors.swift","status":"added","lang":"swift","hunks":[[1,0,1,51]],"header":{"lines":[1,16],"target":"VeilGardeInference","what":[6,11],"pin":[12,15],"in":null,"out":null,"style":"swift"},"marks":[],"first":426,"scopes":[["E","CapturePriors",null,"",18,18,[18,19],51,null,-1,0,"a",[]],["f","apply",["_","_","domain","capture"],"static",19,19,[19,128],50,null,0,0,"a"]],"old":"","new":"//\n//  CapturePriors.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The first compounding step. A valid, present capture signature suppresses every gen-side\n//        head (the combiner is skipped) and, on the screenshot domain only, pins the verdict to\n//        real at P ≤ 0.10. Otherwise the art, blur and human priors are pooled by the stack combiner\n//        into the P(AI); with no combiner in the bundle, a firing prior overrides (the legacy rule).\n//        An art-pair head adjudicates the art head only for a combiner that asks for it; the shipped\n//        one does not.\n//  PIN:  The reference router's capture/prior block: a prior row weighs 1 when its contribution\n//        exceeds 0.5; an art-pair row shows only when the combiner adjudicates and the art head\n//        fired, and weighs 1 when it discounts that fire; pooled > 0.5 is generated, with no\n//        inconclusive band. The noiseprint row and its term left on 2026-10-21.\n//\n\nenum CapturePriors {\n    static func apply(_ state: inout RouteState, _ s: DetectionSignals, domain: DetectionDomain, capture cap: CaptureSignature) {\n        if cap.valid && cap.present {\n            state.stack.append(SpecialistContribution(name: \"capture\", pAI: 0.05, verdict: \"real\", weight: 1.0))\n            if domain == .screenshot { state.p = min(state.p, CaptureLaw.realCeiling); state.verdict = \"real\" }\n            return\n        }\n        let priors = AtlasPriors.evaluate(s)\n        if let comb = HeadRegistry.shared.combiner(in: s.config.bundle), priors.count == comb.wGen.count {\n            let hp = priors.map { $0.contribution.pAI }\n            let pairAI: Float? = {\n                guard comb.pairAdjudicates == true, let h = HeadRegistry.shared.head(.artPair, in: s.config.bundle), let emb = try? s.dinoNorm() else { return nil }\n                return h.pAI(emb)\n            }()\n            let pooled = comb.pool(base: state.p, heads: hp, pairAI: pairAI)\n            for (k, prior) in priors.enumerated() {\n                let influence = comb.contribution(k, base: state.p, heads: hp, pairAI: pairAI)\n                state.stack.append(SpecialistContribution(name: prior.contribution.name, pAI: prior.contribution.pAI,\n                                                          verdict: prior.contribution.verdict, weight: influence > 0.5 ? 1.0 : 0.25))\n            }\n            if let pa = pairAI, !hp.isEmpty, hp[0] > 0.5 {\n                state.stack.append(SpecialistContribution(name: \"art-pair\", pAI: pa, verdict: pa > 0.5 ? \"ai-art\" : \"real-art\", weight: pa < 0.5 ? 1.0 : 0.25))\n            }\n            state.p = pooled\n            state.verdict = pooled > 0.5 ? \"generated\" : \"real\"\n        } else {\n            for prior in priors {\n                state.stack.append(prior.contribution)\n                if prior.fires { state.p = max(state.p, prior.contribution.pAI); state.verdict = \"generated\" }\n            }\n        }\n        if cap.valid { state.stack.append(SpecialistContribution(name: \"capture\", pAI: 0.5, verdict: \"absent\", weight: 0.0)) }\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Route/Mechanisms/FrameSeam.swift","status":"added","lang":"swift","hunks":[[1,0,1,64]],"header":{"lines":[1,16],"target":"VeilGardeInference","what":[6,10],"pin":[11,15],"in":null,"out":null,"style":"swift"},"marks":[],"first":428,"scopes":[["E","FrameSeam",null,"",21,21,[21,15],64,null,-1,0,"a",[]],["f","apply",["_","_","capture","hint","detector"],"static",22,22,[22,154],36,null,0,0,"a"],["f","detectFrame",["_"],"static",39,39,[39,57],63,[38,38],0,0,"a"],["f","stats",["_","_"],"",46,46,[46,83],51,null,2,4,"a"],["f","qualifies",["_"],"",55,55,[55,62],55,null,2,12,"a"]],"old":"","new":"//\n//  FrameSeam.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The frame-seam mechanism (v3.3, live): a fake analog or film border drags the pooled\n//        evidence real-ward while the synthetic content hides inside. When the verdict is real,\n//        capture is absent and P ≥ 0.10, detect a uniform dark frame, re-run the whole stack once\n//        on a wide interior crop that keeps the frame-to-content seam, and take decisive interior\n//        evidence (interior ≥ 0.70 and at least 0.20 above P).\n//  PIN:  Garde's frame block and detectAnalogFrame, unchanged: a 96×96 luma grid, bands of 3% that\n//        qualify when dark (mean < 0.16), uniform (sd < 0.17) and darker than the interior by\n//        > 0.12, at least two qualifying sides, then the fixed rect (5%, 2%, 90%, 96%). The P ≥ 0.10\n//        floor was re-validated 2026-07-19; real film scans read ≤ 0.01 under this rect (6 of 6).\n//        The crop is rendered as a fresh bitmap (renderCrop), never cropping(to:).\n//\n\nimport CoreGraphics\nimport Foundation\n\nenum FrameSeam {\n    static func apply(_ state: inout RouteState, _ s: DetectionSignals, capture cap: CaptureSignature, hint: DetectionDomain?, detector: Detector) throws {\n        guard !s.config.skipFrameCheck, state.verdict == \"real\", !cap.present, state.p >= 0.10,\n              let interiorRect = detectFrame(s.cgImage) else { return }\n        var cfg = s.config\n        cfg.skipFrameCheck = true\n        guard let interior = ImageLoading.renderCrop(s.cgImage, interiorRect) else { return }\n        let sub = try detector.detect(cgImage: interior, config: cfg, hint: hint)\n        let pi = sub.result.p\n        let decisive = pi >= 0.70 && (pi - state.p) >= 0.20\n        state.stack.append(SpecialistContribution(name: \"frame-seam\", pAI: pi, verdict: decisive ? \"generated\" : \"unconfirmed\", weight: decisive ? 1.0 : 0.25))\n        if decisive {\n            state.verdict = \"generated\"\n            state.p = pi\n        }\n    }\n\n    /// The interior rect when the image wears an analog or film frame, else nil.\n    static func detectFrame(_ image: CGImage) -> CGRect? {\n        let N = 96\n        var buf = [UInt8](repeating: 0, count: N * N)\n        guard let ctx = CGContext(data: &buf, width: N, height: N, bitsPerComponent: 8, bytesPerRow: N,\n                                  space: CGColorSpaceCreateDeviceGray(), bitmapInfo: CGImageAlphaInfo.none.rawValue) else { return nil }\n        ctx.interpolationQuality = .low\n        ctx.draw(image, in: CGRect(x: 0, y: 0, width: N, height: N))\n        func stats(_ xs: Range<Int>, _ ys: Range<Int>) -> (mean: Float, sd: Float) {\n            var s: Float = 0, s2: Float = 0, n: Float = 0\n            for y in ys { for x in xs { let v = Float(buf[y * N + x]) / 255; s += v; s2 += v * v; n += 1 } }\n            let m = s / max(n, 1)\n            return (m, max(0, s2 / max(n, 1) - m * m).squareRoot())\n        }\n        // CGContext.draw has a bottom-left origin: buffer row 0 is the IMAGE BOTTOM.\n        let b = Int(Float(N) * 0.03)\n        let interior = stats(b * 4 ..< N - b * 4, b * 4 ..< N - b * 4)\n        func qualifies(_ s: (mean: Float, sd: Float)) -> Bool { s.mean < 0.16 && s.sd < 0.17 && (interior.mean - s.mean) > 0.12 }\n        let imgTop = qualifies(stats(0 ..< N, N - b ..< N))\n        let imgBottom = qualifies(stats(0 ..< N, 0 ..< b))\n        let left = qualifies(stats(0 ..< b, 0 ..< N))\n        let right = qualifies(stats(N - b ..< N, 0 ..< N))\n        guard [imgTop, imgBottom, left, right].filter({ $0 }).count >= 2 else { return nil }\n        let W = CGFloat(image.width), H = CGFloat(image.height)\n        return CGRect(x: W * 0.05, y: H * 0.02, width: W * 0.90, height: H * 0.96)\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Route/Mechanisms/PreviewTail.swift","status":"added","lang":"swift","hunks":[[1,0,1,41]],"header":{"lines":[1,14],"target":"VeilGardeInference","what":[6,9],"pin":[10,13],"in":null,"out":null,"style":"swift"},"marks":[],"first":433,"scopes":[["E","PreviewTail",null,"",16,16,[16,17],41,null,-1,0,"a",[]],["f","apply",["_","_","_","capture","semanticMajority","canDecide"],"static",17,17,[18,64],40,null,0,0,"a"]],"old":"","new":"//\n//  PreviewTail.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The preview-tail arbiter (v3.4, live): sub-512 images (capture invalid) are a physics-empty\n//        regime where the base learned \"small ⇒ AI\". When such an image reads generated with a\n//        clean semantic vote (≤ 0.15), flip to real only if the preview content head reads ≤ 0.45\n//        and the fusion head with the capture shortcut neutralized reads ≤ 0.30.\n//  PIN:  The reference's preview block, cheap gates first: the extra fusion pass runs only on the\n//        rare full-conflict path. A strict tail rescue, not a regime swap: OR-policies raised real\n//        false positives to 20–27% and were rejected (the research record, 2026-07-17, quoted). Two rows: the head's\n//        read (0.25) and the arbiter (1 when it fires).\n//\n\nenum PreviewTail {\n    static func apply(_ chain: inout SemanticChain.Probe, _ state: inout RouteState, _ s: DetectionSignals, capture cap: CaptureSignature,\n                      semanticMajority: Float, canDecide: Bool) {\n        guard !cap.valid, chain.verdict == \"generated\", semanticMajority <= 0.15 else { return }\n        state.semanticTriggered = true\n        state.previewEvaluated = true\n        let phv: Float = {\n            guard let h = HeadRegistry.shared.head(.preview, in: s.config.bundle), let emb = try? s.dinoNorm() else { return -1 }\n            return h.pAI(emb)\n        }()\n        state.previewTriggered = phv >= 0 && phv <= 0.45\n        let pn = (phv >= 0 && phv <= 0.45) ? Fusion.neutralizedBaseP(s) : nil\n        let fires = phv >= 0 && phv <= 0.45 && (pn ?? 1.0) <= 0.30\n        chain.previewDecisive = fires\n        chain.decisive = chain.decisive || fires\n        if phv >= 0 {\n            state.stack.append(SpecialistContribution(name: \"preview-head\", pAI: phv, verdict: phv <= 0.45 ? \"real\" : \"generated\", weight: canDecide ? 0.25 : 0.0))\n        }\n        state.stack.append(SpecialistContribution(name: \"preview-arbiter\", pAI: pn ?? phv, verdict: fires ? \"real\" : \"unconfirmed\",\n                                                  weight: canDecide ? (fires ? 1.0 : 0.25) : 0.0))\n        if fires, let pn {\n            chain.verdict = \"real\"\n            chain.p = min(chain.p, pn)\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Route/Mechanisms/SemanticChain.swift","status":"added","lang":"swift","hunks":[[1,0,1,46]],"header":{"lines":[1,13],"target":"VeilGardeInference","what":[6,8],"pin":[9,12],"in":null,"out":null,"style":"swift"},"marks":[],"first":435,"scopes":[["E","SemanticChain",null,"",15,15,[15,19],46,null,-1,0,"a",[]],["S","Probe",null,"",17,17,[17,17],22,[16,16],0,0,"a"],["f","apply",["_","_","capture"],"static",25,25,[25,117],45,[24,24],0,0,"a"]],"old":"","new":"//\n//  SemanticChain.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The last compounding step, on the semantic-tile map: the preview tail (live), the\n//        authority seam that lets only the production profile commit a probe's revision, and the\n//        semantic-tiles row.\n//  PIN:  The reference's semantic block, in its order. Every probe revises a SHADOW state (Probe);\n//        PublicSurface.project commits it only under `.control`. `.semanticRemoved` never builds\n//        the map, so no ViT forward runs. Zoom escalation, the x-domain gate and the render\n//        taxonomy, none of which ran by default, left on 2026-10-21.\n//\n\nenum SemanticChain {\n    /// The shadow state the probes revise.\n    struct Probe {\n        var p: Float\n        var verdict: String\n        var decisive = false\n        var previewDecisive = false\n    }\n\n    /// The semantic tiles when the map was built, else nil.\n    static func apply(_ state: inout RouteState, _ s: DetectionSignals, capture cap: CaptureSignature) -> [[Float]]? {\n        let profile = s.config.semanticResponsibility\n        let canDecide = profile == .control\n        var probe = Probe(p: state.p, verdict: state.verdict)\n        guard profile != .semanticRemoved, let sm = SemanticTiles.map(s.cgImage, config: s.config) else { return nil }\n        state.semanticMajority = sm.majority\n        state.semanticEvaluated = true\n        let semVerdict = sm.majority > 0.5 ? \"generated\" : \"real\"\n\n        PreviewTail.apply(&probe, &state, s, capture: cap, semanticMajority: sm.majority, canDecide: canDecide)\n\n        let projection = PublicSurface.project(profile: profile, originalP: state.p, originalVerdict: state.verdict,\n                                               probeP: probe.p, probeVerdict: probe.verdict, probeDecisive: probe.decisive)\n        state.p = projection.p\n        state.verdict = projection.verdict\n        state.semanticDecisive = projection.decisive\n        state.previewDecisive = canDecide && probe.previewDecisive\n        state.stack.append(SpecialistContribution(name: \"semantic-tiles\", pAI: sm.majority, verdict: semVerdict,\n                                                  weight: canDecide ? (semVerdict == state.verdict ? 1.0 : 0.25) : 0.0))\n        return sm.grid\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Route/RouteState.swift","status":"added","lang":"swift","hunks":[[1,0,1,28]],"header":{"lines":[1,9],"target":"VeilGardeInference","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":438,"scopes":[["S","RouteState",null,"",11,11,[11,18],28,null,-1,0,"a"],["i","init",["base"],"",23,23,[23,32],27,null,0,0,"a"]],"old":"","new":"//\n//  RouteState.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The router's working state as the mechanisms revise it in order: the P(AI) and\n//        its label, the specialist rows recorded so far, and the trace flags that observe (never\n//        steer) what the semantic and preview probes did.\n//\n\nstruct RouteState {\n    var p: Float\n    var verdict: String\n    var stack: [SpecialistContribution]\n    var semanticMajority: Float? = nil\n    var semanticEvaluated = false\n    var semanticTriggered = false\n    var semanticDecisive = false\n    var previewEvaluated = false\n    var previewTriggered = false\n    var previewDecisive = false\n\n    init(base: InferenceResult) {\n        p = base.p\n        verdict = base.prediction\n        stack = [SpecialistContribution(name: base.scorer, pAI: base.p, verdict: base.prediction, weight: 1.0)]\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Route/Signals.swift","status":"added","lang":"swift","hunks":[[1,0,1,58]],"header":{"lines":[1,12],"target":"VeilGardeInference","what":[6,9],"pin":[10,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":440,"scopes":[["C","DetectionSignals",null,"public final",17,17,[17,57],58,null,-1,0,"a"],["i","init",["cgImage","config"],"public",27,27,[27,59],33,null,0,0,"a"],["f","capture",[],"public",36,36,[36,46],41,[35,35],0,0,"a"],["f","dinoNorm",[],"public",44,44,[44,45],49,[43,43],0,0,"a"],["f","dinoFusion",[],"public",52,52,[52,47],57,[51,51],0,0,"a"]],"old":"","new":"//\n//  Signals.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: What every part of one detection shares, computed once: the image, the config, the\n//        flat-UI screenshot gate (cheap, eager: the domain detector reads it), and, lazily, the\n//        native capture signature and the two DINOv2 embeddings: the fusion head's plain one and\n//        the normalized one the heads read.\n//  PIN:  The reference's signals. The normalized embedding is always the 360×640 force-resize, the\n//        fusion embedding the plain 256/224 preprocessing, both at the config's DINOv2 variant.\n//\n\nimport CoreGraphics\nimport Foundation\n\npublic final class DetectionSignals: @unchecked Sendable {\n    public let cgImage: CGImage\n    public let config: InferenceConfig\n    public let gate: ScreenshotGate\n    public let width: Int\n    public let height: Int\n    private var cachedCapture: CaptureSignature?\n    private var cachedDinoNorm: [Float]?\n    private var cachedDinoFusion: [Float]?\n\n    public init(cgImage: CGImage, config: InferenceConfig) {\n        self.cgImage = cgImage\n        self.config = config\n        self.gate = ScreenshotLens.gate(cgImage)\n        self.width = cgImage.width\n        self.height = cgImage.height\n    }\n\n    /// The native-resolution capture signature.\n    public func capture() -> CaptureSignature {\n        if let c = cachedCapture { return c }\n        let c = CaptureLens.signature(cgImage)\n        cachedCapture = c\n        return c\n    }\n\n    /// The resolution-normalized DINOv2 embedding the specialist heads read.\n    public func dinoNorm() throws -> [Float] {\n        if let e = cachedDinoNorm { return e }\n        let e = try SemanticLens.normalizedEmbedding(cgImage, variant: config.dinoVariant)\n        cachedDinoNorm = e\n        return e\n    }\n\n    /// The plain DINOv2 embedding the fusion head reads.\n    public func dinoFusion() throws -> [Float] {\n        if let e = cachedDinoFusion { return e }\n        let e = try SemanticLens.fusionEmbedding(cgImage, variant: config.dinoVariant)\n        cachedDinoFusion = e\n        return e\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Specialists/AtlasPriors.swift","status":"added","lang":"swift","hunks":[[1,0,1,30]],"header":{"lines":[1,13],"target":"VeilGardeInference","what":[6,9],"pin":[10,12],"in":null,"out":null,"style":"swift"},"marks":[],"first":445,"scopes":[["E","AtlasPriors",null,"",15,15,[15,17],30,null,-1,0,"a",[]],["f","prior",["_","_","_"],"static",19,19,[19,135],24,null,0,0,"a"],["f","evaluate",["_"],"static",27,27,[27,105],29,[26,26],0,0,"a"]],"old":"","new":"//\n//  AtlasPriors.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The three atlas category specialists, cross-domain \"this is AI-generated\" priors on the\n//        normalized embedding: art (AI art against museum and human art), blur (generative blur\n//        against optical blur), human (photoreal AI people against real portraits). Each is\n//        recorded in the stack; the combiner pools them.\n//  PIN:  Garde's atlas specialists: a prior \"fires\" at P ≥ 0.80 (the legacy override when no\n//        combiner ships); its row weighs 1 when firing, 0.25 when consulted. Order art, blur,\n//        human is the combiner's w_gen order. Inert when its head is not in the bundle.\n//\n\nenum AtlasPriors {\n    static let fireThreshold: Float = 0.80\n    static let kinds: [(name: String, kind: HeadKind)] = [(\"art\", .art), (\"blur\", .blur), (\"human\", .human)]\n\n    static func prior(_ name: String, _ kind: HeadKind, _ s: DetectionSignals) -> (contribution: SpecialistContribution, fires: Bool)? {\n        guard let head = HeadRegistry.shared.head(kind, in: s.config.bundle), let emb = try? s.dinoNorm() else { return nil }\n        let p = head.pAI(emb)\n        let fires = p >= fireThreshold\n        return (SpecialistContribution(name: name, pAI: p, verdict: p > head.threshold ? \"generated\" : \"real\", weight: fires ? 1.0 : 0.25), fires)\n    }\n\n    /// Art, blur, human, skipping any head the bundle lacks.\n    static func evaluate(_ s: DetectionSignals) -> [(contribution: SpecialistContribution, fires: Bool)] {\n        kinds.compactMap { prior($0.name, $0.kind, s) }\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Specialists/HeadRegistry.swift","status":"added","lang":"swift","hunks":[[1,0,1,42]],"header":{"lines":[1,12],"target":"VeilGardeInference","what":[6,7],"pin":[8,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":448,"scopes":[["C","HeadRegistry",null,"public final",16,16,[16,53],42,null,-1,0,"a"],["f","head",["_","in"],"public",22,22,[22,81],25,null,0,0,"a"],["f","combiner",["in"],"public",27,27,[27,70],30,null,0,0,"a"],["f","cached",["_","_","_"],"private",32,32,[32,108],41,null,0,0,"a"]],"old":"","new":"//\n//  HeadRegistry.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The specialist heads and the stack combiner of a bundle, each read once per file and\n//        shared. A head the bundle does not name is nil, and the specialist it powers stays inert.\n//  PIN:  The reference's head and combiner caches, keyed by the artifact's path so two\n//        bundles in one process (the live bundle and a candidate under the battery) never mix,\n//        and by the file's modification date and size, so a file the flywheel rewrites in place\n//        (a promote, a restore) is read again.\n//\n\nimport Foundation\n\npublic final class HeadRegistry: @unchecked Sendable {\n    public static let shared = HeadRegistry()\n    private let lock = NSLock()\n    private var heads: [String: (FileStamp, LinearHead?)] = [:]\n    private var combiners: [String: (FileStamp, StackCombiner?)] = [:]\n\n    public func head(_ kind: HeadKind, in bundle: DetectorBundle) -> LinearHead? {\n        guard let url = bundle.url(.head, head: kind) else { return nil }\n        return cached(&heads, url) { try? LinearHead.load($0) }\n    }\n\n    public func combiner(in bundle: DetectorBundle) -> StackCombiner? {\n        guard let url = bundle.url(.combiner) else { return nil }\n        return cached(&combiners, url) { try? StackCombiner.load($0) }\n    }\n\n    private func cached<T>(_ store: inout [String: (FileStamp, T?)], _ url: URL, _ load: (URL) -> T?) -> T? {\n        let key = url.standardizedFileURL.path\n        let stamp = FileStamp(path: key)\n        lock.lock()\n        defer { lock.unlock() }\n        if let hit = store[key], hit.0 == stamp { return hit.1 }\n        let value = load(url)\n        store[key] = (stamp, value)\n        return value\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Specialists/ScreenshotSpecialist.swift","status":"added","lang":"swift","hunks":[[1,0,1,37]],"header":{"lines":[1,14],"target":"VeilGardeInference","what":[6,10],"pin":[11,13],"in":null,"out":null,"style":"swift"},"marks":[],"first":452,"scopes":[["E","ScreenshotSpecialist",null,"public",19,19,[19,33],37,null,-1,0,"a",[]],["f","verdict",["embedding","capture","config"],"static",21,21,[21,136],27,[20,20],0,0,"a"],["f","verdict",["_","config"],"static",30,30,[30,123],36,[29,29],0,0,"a"]],"old":"","new":"//\n//  ScreenshotSpecialist.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The screenshot domain's specialist: a resolution-normalized DINOv2 content head for\n//        social-media screenshots, where the camera-physics fusion false-positives (real reels\n//        read \"generated\"). On its own it applies the capture-present override (a valid sensor\n//        signature pins P toward real); in the stack the router applies that override as a prior,\n//        so the compounding stays legible.\n//  PIN:  The reference's screenshot specialist (v1.10): real false positives 100% → about 8%, → 0% with\n//        the capture prior (the research, quoted). The head's own normalize_size drives its embedding here;\n//        the head's threshold and the config's band make the label.\n//\n\nimport CoreGraphics\nimport Foundation\n\npublic enum ScreenshotSpecialist {\n    /// The head's verdict on a precomputed embedding, with the capture-present override.\n    static func verdict(embedding emb: [Float], capture cap: CaptureSignature, config: InferenceConfig) -> (p: Float, verdict: String)? {\n        guard let head = HeadRegistry.shared.head(.screenshot, in: config.bundle) else { return nil }\n        var p = head.pAI(emb)\n        if cap.present { p = min(p, CaptureLaw.realCeiling) }\n        let t = head.threshold\n        return (p, abs(p - t) < config.decision.band ? \"inconclusive\" : (p > t ? \"generated\" : \"real\"))\n    }\n\n    /// The head's verdict on an image (its own normalize size), with the capture-present override.\n    static func verdict(_ cg: CGImage, config: InferenceConfig) -> (p: Float, verdict: String, capture: CaptureSignature)? {\n        guard let head = HeadRegistry.shared.head(.screenshot, in: config.bundle),\n              let emb = try? SemanticLens.normalizedEmbedding(cg, variant: config.dinoVariant, normW: head.normW, normH: head.normH) else { return nil }\n        let cap = CaptureLens.signature(cg)\n        guard let (p, verdict) = verdict(embedding: emb, capture: cap, config: config) else { return nil }\n        return (p, verdict, cap)\n    }\n}\n"},{"path":"Sources/VeilGardeInference/Specialists/SemanticTiles.swift","status":"added","lang":"swift","hunks":[[1,0,1,30]],"header":{"lines":[1,11],"target":"VeilGardeInference","what":[6,8],"pin":[9,10],"in":null,"out":null,"style":"swift"},"marks":[],"first":455,"scopes":[["E","SemanticTiles",null,"",15,15,[15,19],30,null,-1,0,"a",[]],["f","map",["_","config"],"static",16,16,[16,99],29,null,0,0,"a"]],"old":"","new":"//\n//  SemanticTiles.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The semantic-tile map: the per-patch-token linear head on DINOv2's 16×16 token grid,\n//        P(generated) per token, and the fraction of tokens above 0.5 (the semantic majority). It\n//        powers the router's semantic chain.\n//  PIN:  The reference's semtileMap: tokens of the PLAIN 256/224 input (no force-resize), head\n//        p > 0.5 counted. Nil when the bundle has no semtile head, at zero cost (no ViT forward).\n//\n\nimport CoreGraphics\n\nenum SemanticTiles {\n    static func map(_ cg: CGImage, config: InferenceConfig) -> (grid: [[Float]], majority: Float)? {\n        guard let head = HeadRegistry.shared.head(.semtile, in: config.bundle),\n              let toks = try? SemanticLens.patchTokens(cg, variant: config.dinoVariant) else { return nil }\n        let n = toks.count, d = toks.width\n        let side = Int(Double(n).squareRoot())\n        var grid = [[Float]](repeating: [Float](repeating: 0, count: side), count: side)\n        var gen = 0\n        for t in 0..<n {\n            let p = head.pAI(Array(toks.values[(t * d)..<((t + 1) * d)]))\n            grid[t / side][t % side] = p\n            if p > 0.5 { gen += 1 }\n        }\n        return (grid, Float(gen) / Float(n))\n    }\n}\n"},{"path":"Sources/VeilGardeInference/VeilGardeInference.swift","status":"added","lang":"swift","hunks":[[1,0,1,11]],"header":{"lines":[1,9],"target":"VeilGardeInference","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":457,"scopes":[],"old":"","new":"//\n//  VeilGardeInference.swift\n//  VeilGardeInference\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The detector: the fusion base over DINOv2 and the capture signature, the specialist heads\n//        and their combiner, the router and its mechanisms, composed into one InferenceResult and\n//        its schema-v3 JSON. Re-exports the Lens and Core.\n//\n\n@_exported import VeilGardeLens\n"}]};
